def parse_argspec(s):
    """'a1:sp_stamp' -> (1, ['deref', 'stamp@0']); validates the ops"""
    parts = s.split(':'); m = re.fullmatch(r'a([0-5])', parts[0])
    if not m: raise SystemExit(f'bad argspec {s!r}: must start with a0..a5')
